import{z as i,x as A,o as e,c as B,q as r,j as t,D as o,d as E,s as l,S as s}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"Gemini 1.5 长上下文","description":"","frontmatter":{"title":"Gemini 1.5 长上下文","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/gemini-15.md","filePath":"llm/gemini-15.md","lastUpdated":1791413859000}'),d={name:"llm/gemini-15.md"};function p(m,a,h,F,P,M){const n=A("Mermaid");return e(),B("div",null,[a[2]||(a[2]=r('<h1 id="gemini-1-5-长上下文" tabindex="-1">Gemini 1.5 长上下文 <a class="header-anchor" href="#gemini-1-5-长上下文" aria-label="Permalink to &quot;Gemini 1.5 长上下文&quot;">​</a></h1><div class="epigraph"><p>在至少一千万 token 的上下文里，下一 token 预测仍在改善，跨模态检索召回仍接近完美；生产上把百万级窗口变成可服务的多模态模型。</p><footer>—— Gemini Team，Gemini 1.5: Unlocking multimodal understanding across millions of tokens of context，arXiv:2403.05530</footer></div><p>Gemini 1.5 技术报告（2024 年 3 月初版，后有修订）把<strong>超长上下文</strong>写成这一代的主命题，而不是把 1.0 Ultra 再堆密参数。家族含 <strong>1.5 Pro</strong>（相对同年 2 月 Pro 的更新）与更轻的 <strong>1.5 Flash</strong>。Pro 是稀疏 <strong>MoE Transformer</strong>，用路由把输入送到参数子集，从而在总参数变大时保持每 token 计算可控；Flash 是面向 TPU 服务的解码器，注意力与前馈可并行，并对 Pro <strong>在线蒸馏</strong>，用更高阶预条件优化。二者原生多模态，文本、图像、音视频可交错。研究侧把上下文推到 <strong>10M</strong> token：文本针测约 7M 词、音频约 107 小时、视频约 10.5 小时（1 fps）。生产常见是 1M 量级窗口。报告<strong>没有给出专家数、总参数或激活参数</strong>，本篇也不补。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>2024 年初公开窗口大致是 GPT-4 Turbo 128K、Claude 3 生产 200K。超长文档、整仓代码、数小时录像若切块 + RAG，会丢掉需要跨段绑定的推理，且检索器本身会错。报告要证明两件事：诊断任务上「针」在百万到千万长度仍能取回；现实任务上长文档 QA、长视频 QA、长音频 ASR 超过「短窗口模型 + 外挂检索」。另一件事是效率：1.5 Pro 在多数核心基准上达到或超过 <strong>Gemini 1.0 Ultra</strong>，训练与推理计算却显著更少——长窗口若只能用 Ultra 级稠密模型，服务不可行。</p><p>Flash 的问题是延迟：同样 2M+ 级窗口与多模态，必须给高 QPS 路径一条更小、更快的模型。报告用蒸馏而不是另训一个无关小模型，来减少质量回归。</p><h3 id="针测满分不是长上下文推理" tabindex="-1">针测满分不是长上下文推理 <a class="header-anchor" href="#针测满分不是长上下文推理" aria-label="Permalink to &quot;针测满分不是长上下文推理&quot;">​</a></h3><p>NIAH 只要求找回插入的秘密。1.5 Pro 在文本/视频/音频上到 1M 近乎完美（&gt;99.7% 量级），10M 文本仍约 99.2%；相对 Claude 2.1 在 200K 的 98%，Pro 在 200K 报 100%，并维持到 530K。Flash 到 2M 三模态几乎完美。这些是诊断上限。报告同时做多跳、长文档问答，并承认最难的「把相距很远、又彼此相似的多条事实合起来」在 10M 上仍未完全解决。读 1.5 必须把图 1 的绿格子和真实 QA 分开。</p><p><span class="marginnote">「针测（NIAH）」翻译一下：往几万到几百万 token 的材料里插一句「魔法数字是 XXX」，考模型能不能原样捞回来。它测的是<strong>检索上限</strong>，不是理解深度——所以针测满分不代表长文推理满分，报告自己也承认多跳任务仍难。</span></p><p><span class="marginnote">Kalamang（使用人数少于 200）的 MTOB 设定：把约 500 页参考语法、词典和约 400 条平行句全部放进上下文，让模型学英→Kal 翻译，质量接近用同一材料学习的人。这是长上下文内学习，不是预训练里见过该语言。几乎无网页存在，用来降低污染借口。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>架构公开到这一层为止：Pro 为稀疏 MoE，条件计算来自 Google 一长串 MoE 文献；1.5 还包含「使 10M 理解不掉点」的结构改动，但<strong>没有</strong>把层公式、窗口注意力图案或专家表写进可复现附录。Flash：解码器、注意力与 FFN 并行（报告引用 PaLM 类做法）、从 Pro 蒸馏。服务表：1 万字符输入时 Flash 在英/日/中/法上输出最快；英语超过 650 字符/秒，比当时测过的 Claude 3 Haiku 还快约 30% 以上。</p><p>评测分诊断与现实。诊断：长序列负对数似然——Pro 在长文档上到 1M、代码上到 10M 仍改善，1.0 Pro 约在 32K 饱和；Flash 文档到 1M、代码到 2M。对 NLL 拟合幂律，10M 处出现偏离。现实：长文档/视频 QA，即便给对照模型外挂检索，1.5 Pro 仍全面更好（报告口径）。核心非长上下文能力（数学、科学、代码、多语言、图像/视频/图表）上，Pro 相对 1.0 Pro 在 50 项里 44 项更好，Flash 41 项；并给出分域平均提升百分比。负责任部署与模型卡在附录。</p>',13)),(e(),t(s,null,{default:o(()=>[l(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22Gemini%201.5%20%E5%AE%B6%E6%97%8F%22%5D%20--%3E%20P%5B%22Pro%EF%BC%9A%E7%A8%80%E7%96%8F%20MoE%22%5D%0A%20%20F%20--%3E%20FL%5B%22Flash%EF%BC%9A%E8%92%B8%E9%A6%8F%20%2B%20%E4%BD%8E%E5%BB%B6%E8%BF%9F%22%5D%0A%20%20P%20--%3E%20CTX%5B%22%E7%A0%94%E7%A9%B6%E8%87%B3%2010M%EF%BC%9B%E6%9C%8D%E5%8A%A1%E5%B8%B8%E8%A7%81%201M%22%5D%0A%20%20FL%20--%3E%20CTX2%5B%222M%2B%20%E7%AA%97%E5%8F%A3%22%5D%0A%20%20CTX%20--%3E%20NIAH%5B%22%E8%B7%A8%E6%A8%A1%E6%80%81%E9%92%88%E6%B5%8B%22%5D%0A%20%20CTX%20--%3E%20QA%5B%22%E9%95%BF%E6%96%87%E6%A1%A3%20%2F%20%E9%95%BF%E8%A7%86%E9%A2%91%20QA%22%5D%0A%20%20CTX%20--%3E%20MTOB%5B%22%E8%AF%AD%E6%B3%95%E4%B9%A6%E5%86%85%E5%AD%A6%E4%B9%A0%E7%BF%BB%E8%AF%91%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<h3 id="模态是交错的-不是三个窗口" tabindex="-1">模态是交错的，不是三个窗口 <a class="header-anchor" href="#模态是交错的-不是三个窗口" aria-label="Permalink to &quot;模态是交错的，不是三个窗口&quot;">​</a></h3><p>10M 可以几乎五天音频、或《战争与和平》十倍以上、或 Flax 仓库量级代码、或 10.5 小时 1 fps 视频。因为原生多模态，这些可以混在同一前缀。针测按模态分别插针；真实任务则要求在录像里对齐口播与画面再回答。ASR 长音频是另一张表，不要用文本 NIAH 代替。生产 1M 与研究 10M 的服务成本差几个数量级，API 档位以 Google 当时文档为准。</p><p><span class="marginnote">给个数感受 10M 有多长：《战争与和平》约 58 万词，10M token 是它的十倍以上；按音频算是约五天连续语音，按 1 fps 视频是约 10.5 小时。对照当年 GPT-4 Turbo 的 128K，10M 约等于 78 个 128K 窗口并排——这就是「代际跳跃」修辞的实际含义。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>MoE 的机制是总参数与每 token FLOPs 解耦：路由只激活子集。报告用这一点解释「比 1.0 Ultra 省很多计算却对上质量」。长上下文的机制在公开文本里是「一系列架构改动 + 训练/服务基础设施」，<strong>不足以</strong>复现注意力核。能确定的经验规律是：NLL 随位置在很长一段上仍降，说明模型在用远距离统计，而不只是局部窗口；10M 幂律偏离说明外推有墙。蒸馏让 Flash 继承 Pro 的长窗行为，但代码 NLL 只画到 2M，不要把 Pro 的 10M 曲线抄给 Flash。</p><p>相对 RAG：外挂检索把「找对段落」从模型内部分出。1.5 的主张是部分任务上内生长窗已超过检索增强的短窗模型。这不废除 RAG——延迟、价格、隐私仍可能要求切块——只是把「窗口太短所以必须 RAG」从技术必然变成成本选择。</p>',6)),(e(),t(s,null,{default:o(()=>[l(n,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20LEN%5B%22%E4%B8%8A%E4%B8%8B%E6%96%87%E8%B6%8A%E6%8B%89%E8%B6%8A%E9%95%BF%22%5D%20--%3E%20Q%7B%22%E5%93%AA%E4%BA%9B%E6%88%90%E6%9C%AC%E8%A2%AB%E8%A7%A3%E8%80%A6%E4%BA%86%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22MoE%20%E8%B7%AF%E7%94%B1%22%7C%20YES%5B%22%E6%AF%8F%20token%20%E5%8F%AA%E6%BF%80%E6%B4%BB%E5%8F%82%E6%95%B0%E5%AD%90%E9%9B%86%22%5D%0A%20%20YES%20--%3E%20YES2%5B%22%E5%B1%82%E5%86%85%20FLOPs%20%E8%BF%91%E4%BC%BC%E4%B8%8D%E6%B6%A8%EF%BC%9A%E7%AE%97%E5%BE%97%E8%B5%B7%22%5D%0A%20%20Q%20--%3E%7C%22%E6%B3%A8%E6%84%8F%E5%8A%9B%20KV%22%7C%20NO%5B%22%E7%BC%93%E5%AD%98%E9%9A%8F%20token%20%E6%95%B0%E7%BA%BF%E6%80%A7%E6%B6%A8%22%5D%0A%20%20NO%20--%3E%20NO2%5B%22%E6%98%BE%E5%AD%98%E4%B8%8E%E5%B8%A6%E5%AE%BD%E7%85%A7%E4%BB%98%EF%BC%9A%E5%AD%98%E4%B8%8D%E8%B5%B7%E5%B0%B1%E8%A6%81%E7%B3%BB%E7%BB%9F%E6%9D%A5%E6%89%9B%22%5D%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<p><span class="marginnote">初学者容易以为稀疏 MoE 连 KV 缓存也一起省了——没有。MoE 只在层内少激活几个专家、省的是每 token 的计算量；注意力键值缓存仍随上下文长度线性涨，1M 上下文的显存与带宽成本一分不少。这就是为什么长窗口是「架构 + 服务基础设施」合力的成果。</span></p><p><span class="marginnote">不要给 1.5 Pro 填专家数或「激活 22B」之类来路不明的数字。报告只说稀疏 MoE 与条件计算。Flash 是否稠密，文中写 transformer decoder 与蒸馏，未给出与 Pro 对等的 MoE 句子；不要断言 Flash 的专家布局。</span></p><h3 id="与-claude-3-gpt-4-turbo-的窗口对比" tabindex="-1">与 Claude 3 / GPT-4 Turbo 的窗口对比 <a class="header-anchor" href="#与-claude-3-gpt-4-turbo-的窗口对比" aria-label="Permalink to &quot;与 Claude 3 / GPT-4 Turbo 的窗口对比&quot;">​</a></h3><p>报告把 10M 写成相对 Claude 3.0 200K 与 GPT-4 Turbo 128K 的代际跳跃。针测对照 Claude 2.1 的 200K。这些是 1.5 报告写作时的公开窗口，随后 Claude 与 GPT 都拉长过；历史对比应钉死 2403.05530 用的对手版本，不要用 2025 年的 1M Claude 去改写 1.5 的「代际」修辞。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>无参数、无训练 token、无具体稀疏度。10M 是研究评测长度，不是所有 API 用户的默认配额。针测用秘密数字/短语，对抗性相似事实的多跳仍难。Kalamang 展示的是语法书内翻译，不是任意低资源语言的零成本习得。视频 1 fps 会丢掉帧间事件；小时级理解不等于动作定位到百分之一秒。服务上 KV 随长度涨，MoE 省的是层内 FLOPs，不是自动省缓存；长请求的墙钟与计费是产品约束。</p><p>把 1.5 写成「只有长上下文、核心能力弱」与报告的 44/50 项相反；写成「10M 已解决长推理」又与报告自己的难任务保留段相反。Flash 的卖点是速度与价格，质量以报告相对 1.0 Pro/Ultra 的表为准，不要用 Pro 的 10M 视频数字代替 Flash。</p><p><span class="marginnote">出处：Gemini Team，<em>Gemini 1.5: Unlocking multimodal understanding across millions of tokens of context</em>，arXiv:2403.05530。参数量与专家表未公开。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Gemini 1.5 Pro：稀疏 MoE 多模态，研究上下文至 10M，针测近乎完美；核心基准对标或超过 1.0 Ultra 且更省计算。</li><li>Flash：从 Pro 蒸馏的低延迟档，2M+ 窗口，输出吞吐公开表上领先。</li><li>针测、NLL 幂律、长 QA、MTOB 语法书翻译是四类不同证据，不可互相替代。</li><li>不公开参数与专家数；生产窗口以当时 API 为准，常为 1M 而非 10M。</li><li>出处：arXiv:2403.05530。</li></ul>',10))])}const T=i(d,[["render",p]]);export{g as __pageData,T as default};
